  function videoProfile(level=0,fixedScaleResolutionDownBy){const base=baseVideoProfile(mediaPeerCount()),steps=[{bitrate:1,fps:0},{bitrate:.72,fps:2},{bitrate:.52,fps:4}],step=steps[Math.min(2,Math.max(0,level))];return {...base,label:`${base.label}${level?`・低負荷${level}`:""}`,maxBitrate:Math.round(base.maxBitrate*step.bitrate),maxFramerate:Math.max(8,base.maxFramerate-step.fps),scaleResolutionDownBy:fixedScaleResolutionDownBy??base.scaleResolutionDownBy};}
  async function setSenderParameters(sender,values,degradationPreference,configureResolution=false){if(!sender?.getParameters||!sender?.setParameters)return false;const apply=async(full)=>{const parameters=sender.getParameters()||{};if(!parameters.encodings?.length)parameters.encodings=[{}];const encoding=parameters.encodings[0];encoding.maxBitrate=values.maxBitrate;if(values.maxFramerate)encoding.maxFramerate=values.maxFramerate;if(full&&configureResolution&&values.scaleResolutionDownBy)encoding.scaleResolutionDownBy=values.scaleResolutionDownBy;if(full&&values.priority){encoding.priority=values.priority;encoding.networkPriority=values.priority;}if(full&&degradationPreference)parameters.degradationPreference=degradationPreference;await sender.setParameters(parameters);};try{await apply(true);return true;}catch{try{await apply(false);return true;}catch{return false;}}}
