  function updateRemoteMediaState(peerId){const entry=state.peers.get(peerId),tile=entry?.tile;if(!tile)return;const media=state.remoteMediaStates.get(peerId),videoOff=media?.video===false,audioOff=media?.audio===false;let overlay=tile.querySelector(".camera-off"),badge=tile.querySelector(".mic-off");if(videoOff&&!overlay){overlay=document.createElement("div");overlay.className="camera-off";overlay.innerHTML="<strong>📹 ビデオ OFF</strong><small>相手がカメラをオフにしています</small>";tile.append(overlay);}else if(!videoOff)overlay?.remove();if(audioOff&&!badge){badge=document.createElement("div");badge.className="mic-off";badge.innerHTML='<span class="mic-glyph" aria-hidden="true"></span>';badge.setAttribute("aria-label","マイクオフ");tile.append(badge);}else if(!audioOff)badge?.remove();if(peerId===state.featuredPeerId)updateFeaturedMediaState();}
  function tileFor(peer,stream){let tile=[...ui["remote-grid"].children].find((item)=>item.dataset.peerId===peer.id);if(!tile){tile=document.createElement("figure");tile.className="remote-tile";tile.dataset.peerId=peer.id;const video=document.createElement("video");video.autoplay=true;video.playsInline=true;const caption=document.createElement("figcaption");caption.textContent=peer.name;tile.append(video,caption);tile.onclick=()=>{if(state.suppressTileClick)return;state.featuredPeerId=peer.id;state.layoutSignature="";scheduleLayout();};ui["remote-grid"].append(tile);}tile.classList.remove("hidden");tile.querySelector("figcaption").textContent=peer.name;const video=tile.querySelector("video");video.srcObject=stream;video.play?.().catch(()=>{});const entry=state.peers.get(peer.id);if(entry)entry.tile=tile;updateRemoteMediaState(peer.id);scheduleLayout();return tile;}
