  function thumbnailLayout(){const portrait=window.innerHeight>window.innerWidth,width=Math.min(portrait?150:240,Math.max(portrait?105:140,window.innerWidth*(portrait?.24:.19)));return {edge:portrait?10:14,step:width*.75+12};}
  function updateLayout(){const tiles=[...ui["remote-grid"].children].filter((tile)=>tile.querySelector("video")?.srcObject);const ids=tiles.map((tile)=>tile.dataset.peerId);if(!ids.includes(state.featuredPeerId))state.featuredPeerId=ids[0]||null;const signature=`${state.featuredPeerId||"none"}:${ids.join(",")}`;if(signature===state.layoutSignature){updateFeaturedMediaState();return;}state.layoutSignature=signature;const thumbnail=thumbnailLayout();tiles.sort((a,b)=>a.dataset.peerId===state.featuredPeerId?-1:b.dataset.peerId===state.featuredPeerId?1:0).forEach((tile,index)=>{tile.classList.toggle("main",index===0);tile.classList.toggle("thumbnail",index>0);tile.style.right=index>0?`${thumbnail.edge}px`:"";tile.style.bottom=index>0?`${thumbnail.edge+(index-1)*thumbnail.step}px`:"";ui["remote-grid"].append(tile);});const featured=state.featuredPeerId?state.presence.get(state.featuredPeerId):null;ui["featured-name"].textContent=featured?.name||"";ui["featured-name"].classList.toggle("hidden",!featured);updateFeaturedMediaState();ui["empty-state"].classList.toggle("hidden",tiles.length>0);ui["peer-summary"].textContent=tiles.length?`${tiles.length}台と接続中`:"接続相手を待っています";setStatus(tiles.length?"接続済み":"相手を待っています",tiles.length?"connected":"offline");}
